def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def _info(t):
    """Adds parent[k] (-1 for the root) and depth[k]. Parents come before children in level order."""
    vals, left, right = _links(t)
    n = len(vals)
    par = [-1] * n
    depth = [0] * n
    for k in range(n):
        for c in (left[k], right[k]):
            if c != -1:
                par[c] = k
                depth[c] = depth[k] + 1
    return vals, left, right, par, depth


def deepestLeavesLCA(tree):
    vals, left, right, par, depth = _info(tree)
    n = len(vals)
    md = [0] * n
    res = [0] * n
    for k in range(n - 1, -1, -1):
        l, r = left[k], right[k]
        a = md[l] if l != -1 else -1
        b = md[r] if r != -1 else -1
        if l == -1 and r == -1:
            md[k] = depth[k]
            res[k] = k
        elif a == b:
            md[k] = a
            res[k] = k
        elif a > b:
            md[k] = a
            res[k] = res[l]
        else:
            md[k] = b
            res[k] = res[r]
    return vals[res[0]]
